def run_mega_seed(db: MemoryDB) -> None:
    # Verifica se já foi aplicado
    existing = db.get_preference("psicologia:autoestima", "")
    if existing:
        log.info("Mega seed já aplicado — ignorando.")
        return

    log.info("Aplicando mega seed: %d entradas...", len(KNOWLEDGE))
    for key, value in KNOWLEDGE:
        db.set_preference(key, value)
    log.info("Mega seed concluído: %d entradas salvas.", len(KNOWLEDGE))


if __name__ == "__main__":
    import logging as _logging
    _logging.basicConfig(level=_logging.INFO, format="%(message)s")
    config = load_config()
    db = MemoryDB(config.memory.db_path)
    db.initialize()
    run_mega_seed(db)
    print(f"\nBanco atualizado. Entradas adicionadas: {len(KNOWLEDGE)}")
